function primeMusicAudio(){const a=ensureMusicAudio();if(current){syncRoomMusic(true);return}if(a.src)return;try{a.src=MUSIC_TRACKS[0].src;a.load();a.volume=0;const p=a.play();if(p?.then)p.then(()=>{a.pause();a.currentTime=0;refreshMusicVolume()}).catch(()=>{})}catch{}}
function scheduleMusicBoundary(track,offset){clearTimeout(musicSyncTimer);const remaining=Math.max(.35,(track.duration-Math.max(0,offset))+.12);musicSyncTimer=setTimeout(()=>syncRoomMusic(true),Math.min(2147483000,remaining*1000))}
function syncRoomMusic(force=false){if(!current||!sound||musicLevel<=0){if(musicAudio)musicAudio.pause();return}const plan=musicPlan();if(!plan)return;const a=ensureMusicAudio(),track=MUSIC_TRACKS[plan.track],generation=musicGeneration;const isNewTrack=musicRoom!==current.code||musicTrack!==plan.track||!a.src.endsWith(track.src);const start=(allowSeek=true)=>{if(generation!==musicGeneration||!current||!sound||musicLevel<=0)return;const fresh=musicPlan();if(!fresh)return;if(fresh.track!==plan.track){syncRoomMusic(true);return}try{if(a.readyState>=1&&Number.isFinite(a.duration)){const safe=Math.max(0,Math.min(fresh.offset,Math.max(0,a.duration-.08)));const drift=Math.abs((a.currentTime||0)-safe);const canCorrect=performance.now()-musicLastSeekAt>8000;if(allowSeek&&(isNewTrack||a.paused||(force&&drift>4&&canCorrect))){a.currentTime=safe;musicLastSeekAt=performance.now()}}refreshMusicVolume();const play=a.play();if(play?.catch)play.catch(()=>{});scheduleMusicBoundary(track,fresh.offset)}catch{}};if(isNewTrack){clearTimeout(musicSyncTimer);musicRoom=current.code;musicTrack=plan.track;a.pause();a.src=track.src;a.load();a.addEventListener('loadedmetadata',()=>start(true),{once:true})}else{refreshMusicVolume();if(a.paused)start(true);else{const fresh=musicPlan();if(fresh?.track===plan.track)scheduleMusicBoundary(track,fresh.offset)}}}
function syncSoundButtons(){$('sound').textContent=`Sonido: ${sound?'encendido':'apagado'}`;$('sound').setAttribute('aria-pressed',sound);$('fabSound').classList.toggle('active',sound);$('fabSound').setAttribute('aria-pressed',String(sound));$('fabSound').setAttribute('aria-label',sound?'Apagar sonido':'Encender sonido')}
function syncVolumeControls(){if($('effectsVolume'))$('effectsVolume').value=String(Math.round(effectsLevel));if($('musicVolume'))$('musicVolume').value=String(Math.round(musicLevel))}
function toggleSound(){sound=!sound;sfxGeneration++;stopActiveSfx();sfxQueue=Promise.resolve();sfxQueued=0;syncSoundButtons();if(sound){preloadSfx();syncRoomMusic(true)}else stopRoomMusic(false)}
$('sound').onclick=toggleSound;$('fabSound').onclick=()=>{toggleSound();setFab(false)};$('fabToggle').onclick=e=>{e.stopPropagation();setFab(!fabOpen)};$('fabEditor').onclick=()=>{setFab(false);window.open('/editor/','_blank','noopener')};
$('effectsVolume').oninput=e=>{effectsLevel=Math.max(0,Math.min(100,Number(e.target.value)||0));try{localStorage.setItem('kaoru-effects-volume',String(effectsLevel))}catch{}for(const [key,a]of sfxPreloaded)a.volume=sfxVolume(SFX[key]);if(sfxActive?.__kaoruGameFx){const entry=Object.values(SFX).find(def=>sfxActive.src.endsWith(def.src));if(entry)sfxActive.volume=sfxVolume(entry)}};
$('musicVolume').oninput=e=>{musicLevel=Math.max(0,Math.min(100,Number(e.target.value)||0));try{localStorage.setItem('kaoru-music-volume',String(musicLevel))}catch{}refreshMusicVolume();if(musicLevel>0){if(musicAudio?.paused)syncRoomMusic(true)}else if(musicAudio)musicAudio.pause()};
document.addEventListener('click',e=>{if(fabOpen&&!$('gameFab').contains(e.target))setFab(false)});document.addEventListener('pointerdown',e=>{if(current&&musicAudio?.paused)syncRoomMusic(true);else if(!current)primeMusicAudio();if(centerLocked||visualBusy)return;if(e.target.closest('button,a,[role="button"],summary'))playClickImmediate()},{capture:true});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&fabOpen)setFab(false)});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&current&&sound&&musicLevel>0)syncRoomMusic(true)});syncSoundButtons();syncVolumeControls();if(sound)preloadSfx();

