const CHAT_FLAG_CODES=["AW","AF","AO","AI","AX","AL","AD","AE","AR","AM","AS","AQ","TF","AG","AU","AT","AZ","BI","BE","BJ","BQ","BF","BD","BG","BH","BS","BA","BL","BY","BZ","BM","BO","BR","BB","BN","BT","BV","BW","CF","CA","CC","CH","CL","CN","CI","CM","CD","CG","CK","CO","KM","CV","CR","CU","CW","CX","KY","CY","CZ","DE","DJ","DM","DK","DO","DZ","EC","EG","ER","EH","ES","EE","ET","FI","FJ","FK","FR","FO","FM","GA","GB","GE","GG","GH","GI","GN","GP","GM","GW","GQ","GR","GD","GL","GT","GF","GU","GY","HK","HM","HN","HR","HT","HU","ID","IM","IN","IO","IE","IR","IQ","IS","IL","IT","JM","JE","JO","JP","KZ","KE","KG","KH","KI","KN","KR","KW","LA","LB","LR","LY","LC","LI","LK","LS","LT","LU","LV","MO","MF","MA","MC","MD","MG","MV","MX","MH","MK","ML","MT","MM","ME","MN","MP","MZ","MR","MS","MQ","MU","MW","MY","YT","NA","NC","NE","NF","NG","NI","NU","NL","NO","NP","NR","NZ","OM","PK","PA","PN","PE","PH","PW","PG","PL","PR","KP","PT","PY","PS","PF","QA","RE","RO","RU","RW","SA","SD","SN","SG","GS","SH","SJ","SB","SL","SV","SM","SO","PM","RS","SS","ST","SR","SK","SI","SE","SZ","SX","SC","SY","TC","TD","TG","TH","TJ","TK","TM","TL","TO","TT","TN","TR","TV","TW","TZ","UG","UA","UM","UY","US","UZ","VA","VC","VE","VG","VI","VN","VU","WF","WS","YE","ZA","ZM","ZW"];
const CHAT_SKIN_BASES=["👋","🤚","🖐️","✋","🖖","🫱","🫲","🫳","🫴","👌","🤌","🤏","✌️","🤞","🫰","🤟","🤘","🤙","👈","👉","👆","👇","☝️","🫵","👍","👎","✊","👊","🤛","🤜","👏","🙌","🫶","👐","🤲","🙏","✍️","💅","🤳","💪","🦵","🦶","👂","👃","👶","🧒","👦","👧","🧑","👨","👩","🧓","👴","👵","🙍","🙎","🙅","🙆","💁","🙋","🧏","🙇","🤦","🤷"];
const CHAT_SKIN_MODS=["🏻","🏼","🏽","🏾","🏿"];
let chatEmojiCategory='recent';
function flagEmoji(code){return [...code].map(ch=>String.fromCodePoint(127397+ch.charCodeAt())).join('')}
function normalizeClientHex(value,fallback='#000000'){let s=String(value||'').trim().toLowerCase();if(/^[0-9a-f]{3}$/.test(s))s='#'+s;if(/^#[0-9a-f]{3}$/.test(s))s='#'+[...s.slice(1)].map(x=>x+x).join('');if(/^[0-9a-f]{6}$/.test(s))s='#'+s;return /^#[0-9a-f]{6}$/.test(s)?s:fallback}
function normalizeClientChatStyle(value={}){const align=['left','center','right'].includes(value?.textAlign)?value.textAlign:'left';return {mode:value?.mode==='solid'?'solid':'gradient',bubble1:normalizeClientHex(value?.bubble1,'#dba9f6'),bubble2:normalizeClientHex(value?.bubble2,'#f5a9d4'),text:normalizeClientHex(value?.text,'#2e1736'),angle:Math.round(Math.max(0,Math.min(360,Number(value?.angle)||135))),fontSize:Math.round(Math.max(11,Math.min(24,Number(value?.fontSize)||14))),textAlign:align,textX:Math.round(Math.max(-10,Math.min(10,Number(value?.textX)||0))),textY:Math.round(Math.max(-10,Math.min(10,Number(value?.textY)||0)))}}
function generatedExtraEmojis(){const seen=new Set(CHAT_EMOJI_CATEGORIES.flatMap(c=>c.items||[])),out=[];for(const base of CHAT_SKIN_BASES)for(const mod of CHAT_SKIN_MODS){const x=base.replace(/\ufe0f/g,'')+mod;if(!seen.has(x)){seen.add(x);out.push(x)}}for(const [a,b] of [[0x203c,0x3299],[0x1f000,0x1faff]])for(let cp=a;cp<=b;cp++){const ch=String.fromCodePoint(cp);try{if(/\p{Extended_Pictographic}/u.test(ch)&&!seen.has(ch)){seen.add(ch);out.push(ch)}}catch{}}return out}
const CHAT_EXTRA_EMOJIS=generatedExtraEmojis();
function emojiItemsForCategory(id){if(id==='recent')return chatProfileState.recentEmojis||[];if(id==='flags')return CHAT_FLAG_CODES.map(flagEmoji);if(id==='extras')return CHAT_EXTRA_EMOJIS;if(id==='kaomoji')return CHAT_KAOMOJI;return CHAT_EMOJI_CATEGORIES.find(x=>x.id===id)?.items||[]}
function setChatMinimized(value){chatMinimized=!!value;const chat=$('roomChat');if(!chat)return;chat.classList.toggle('minimized',chatMinimized);const title=chat.querySelector('.chat-title strong');if(title)title.textContent=chatMinimized?'Chat':'Chat de la sala';$('chatMinimize').textContent=chatMinimized?'↗':'—';$('chatMinimize').setAttribute('aria-label',chatMinimized?'Abrir chat completo':'Minimizar chat');$('chatMinimize').title=chatMinimized?'Abrir chat completo':'Minimizar chat';if(!chatMinimized){chatUnread=0;updateChatUnread();setTimeout(scrollChatBottom,60)}}
function updateChatUnread(){const el=$('chatUnread');if(!el)return;el.hidden=!chatUnread;el.textContent=chatUnread>99?'99+':String(chatUnread);$('roomChat')?.classList.toggle('has-unread',chatUnread>0)}
function stopRoomChat(){chatStream?.close();chatStream=null;chatRoom=null;chatUnread=0;seenChatIds.clear();updateChatUnread();const chat=$('roomChat');if(chat){chat.hidden=true;chat.classList.remove('minimized','has-unread')}const picker=$('chatPicker');if(picker)picker.hidden=true}
function scrollChatBottom(){const box=$('chatMessages');if(box)box.scrollTop=box.scrollHeight}
function chatMember(id){return current?.members?.find(m=>m.id===id)||{id,name:'Jugador@',chatStyle:null}}
function chatStickerUrl(id){return `/api/chat/stickers/${encodeURIComponent(id)}/image`}
const chatFontLoads=new Map();
function chatStyleFor(id){if(id===me?.id)return normalizeClientChatStyle(chatProfileState.chatStyle||me?.chatStyle);return normalizeClientChatStyle(chatMember(id)?.chatStyle)}
function chatFontFor(id){if(id===me?.id)return chatProfileState.chatFont||me?.chatFont||null;return chatMember(id)?.chatFont||null}
async function ensureChatFont(id){const meta=chatFontFor(id);if(!meta?.url||!meta.version||typeof FontFace==='undefined')return '';const key=`${id}:${meta.version}`;if(chatFontLoads.has(key))return chatFontLoads.get(key);const family=`KaoruChat_${String(id).replace(/[^a-z0-9]/gi,'_')}_${meta.version}`;const task=(async()=>{try{const face=new FontFace(family,`url("${meta.url}")`);await face.load();document.fonts.add(face);return family}catch{return ''}})();chatFontLoads.set(key,task);return task}
function applyChatBubbleStyle(bubble,style,userId){style=normalizeClientChatStyle(style);bubble.style.background=style.mode==='solid'?style.bubble1:`linear-gradient(${style.angle}deg,${style.bubble1},${style.bubble2})`;bubble.style.color=style.text;bubble.style.fontSize=`${style.fontSize}px`;bubble.style.textAlign=style.textAlign;const text=bubble.querySelector('.chat-text,.chat-preview-text');if(text)text.style.transform=`translate(${style.textX}px,${style.textY}px)`;bubble.style.fontFamily='Arial,sans-serif';if(userId)ensureChatFont(userId).then(family=>{if(family&&bubble.isConnected)bubble.style.fontFamily=`"${family}",Arial,sans-serif`})}
function chatAvatar(member){const av=avatar(member);av.classList.add('chat-avatar');av.setAttribute('aria-hidden','true');return av}
function refreshRenderedChatProfiles(){for(const wrap of document.querySelectorAll('#chatMessages .chat-message')){const id=wrap.dataset.userId,member=chatMember(id),old=wrap.querySelector('.chat-avatar');if(old)old.replaceWith(chatAvatar(member));if(!wrap.classList.contains('sticker')){const bubble=wrap.querySelector('.chat-bubble');if(bubble)applyChatBubbleStyle(bubble,chatStyleFor(id),id)}}}
